package repository;

import domain.Utilizator;
import validators.Validator;

import java.sql.*;
import java.util.ArrayList;
import java.util.List;

/**
 * Database repository for users (PostgreSQL, table users), implemented with JDBC.
 * The id of a new user is generated by the database.
 */
public class UtilizatorDbRepository implements Repository<Integer, Utilizator> {
    private final Validator<Utilizator> validator;
    private final String url;
    private final String user;
    private final String password;

    /**
     * Creates the repository with the connection parameters.
     *
     * @param validator the validation strategy
     * @param url the database url
     * @param user the database user
     * @param password the database password
     */
    public UtilizatorDbRepository(Validator<Utilizator> validator, String url, String user, String password) {
        this.validator = validator;
        this.url = url;
        this.user = user;
        this.password = password;
    }

    /**
     * Finds a user by id.
     *
     * @param id the user id
     * @return the user, or null if there is no user with this id
     * @throws IllegalArgumentException if id is null
     * @throws RepositoryException if the database cannot be accessed
     */
    @Override
    public Utilizator findOne(Integer id) {
      if(id==null)throw new IllegalArgumentException("Id-ul nu poate fi null");
      try(
              Connection c=DriverManager.getConnection(url,user,password);
              PreparedStatement ps=c.prepareStatement("SELECT * FROM users WHERE  id=?"))
      {
          ps.setInt(1,id);
          try(ResultSet rs=ps.executeQuery())
          {
              if(rs.next())
              {
                  Utilizator nou=new Utilizator(rs.getInt("id"),rs.getString("last_name"),rs.getString("first_name"));
                  return nou;
              }
              return null;
          }

      }
      catch (SQLException e)
      {
          throw new RepositoryException("Eroare la cautarea utilizatorului: "+e.getMessage(),e);
      }
    }

    /**
     * Returns all users, ordered by id.
     *
     * @return all users from the database
     * @throws RepositoryException if the database cannot be accessed
     */
    @Override
    public Iterable<Utilizator> findAll()
    {
     List<Utilizator> utilizatori=new ArrayList<>();
     try(
             Connection c = DriverManager.getConnection(url,user,password);
             PreparedStatement ps=c.prepareStatement("SELECT * FROM users ORDER BY ID");
             ResultSet rs=ps.executeQuery())
        {
         while(rs.next())
         {
             Utilizator nou=new Utilizator(rs.getInt("id"),rs.getString("last_name"),rs.getString("first_name"));
             utilizatori.add(nou);
         }
        }
        catch(SQLException e)
        {
            throw new RepositoryException("Nu s-au putut citi utilizatorii: "+e.getMessage(),e);
        }
     return utilizatori;
    }

    /**
     * Saves a user; the database generates the id, which is then set on the entity.
     *
     * @param entity the user to save
     * @return null if the user was saved
     * @throws IllegalArgumentException if entity is null
     * @throws validators.ValidationException if the user is not valid
     * @throws RepositoryException if the database cannot be accessed
     */
    @Override
    public Utilizator save(Utilizator entity) {
        if (entity == null) throw new IllegalArgumentException("Utilizatorul nu poate fi null");
        validator.validate(entity);
        String sql = "INSERT INTO users(first_name,last_name) VALUES(?,?)";
        try (
           Connection c=DriverManager.getConnection(url,user,password);
           PreparedStatement ps= c.prepareStatement(sql,Statement.RETURN_GENERATED_KEYS))
        {
            ps.setString(1,entity.getPrenume());
            ps.setString(2,entity.getNume());
            ps.executeUpdate();
            try(ResultSet keys=ps.getGeneratedKeys())
            {
                if(keys.next())
                {
                    entity.setId(keys.getInt(1));
                }
            }
    }
        catch(SQLException e)
        {
            throw new RepositoryException("Eroare la salvarea utilizatorului: "+e.getMessage(),e);
        }
        return null;
    }

    /**
     * Deletes a user by id; the friendships of the user are removed by ON DELETE CASCADE.
     *
     * @param id the user id
     * @return the deleted user, or null if there is no user with this id
     * @throws IllegalArgumentException if id is null
     * @throws RepositoryException if the database cannot be accessed
     */
    @Override
    public Utilizator delete(Integer id) {
        Utilizator gasit=findOne(id);
        if(gasit==null)return null;
        String sql="DELETE FROM users WHERE id = ?";
        try(
                Connection c=DriverManager.getConnection(url,user,password);
                PreparedStatement ps= c.prepareStatement(sql);
                )
        {
            ps.setInt(1,id);
            ps.executeUpdate();
            return  gasit;

        }
        catch (SQLException e)
        {
            throw new RepositoryException("Eroare la stergerea utilizatorului: "+e.getMessage(),e);
        }
    }

    /**
     * Updates the names of a user.
     *
     * @param entity the user with the new names
     * @return null if the user was updated, or the entity if there is no user with its id
     * @throws IllegalArgumentException if entity is null
     * @throws validators.ValidationException if the user is not valid
     * @throws RepositoryException if the database cannot be accessed
     */
    @Override
    public Utilizator update(Utilizator entity) {
       if(entity==null)
       {
           throw new IllegalArgumentException("Utilizatorul nu poate fi null");
       }
       validator.validate(entity);
       String sql="UPDATE users SET last_name= ?, first_name=? WHERE id =?";
        try(
                Connection c=DriverManager.getConnection(url,user,password);
                PreparedStatement ps= c.prepareStatement(sql);
        )
        {
            ps.setString(1,entity.getNume());
            ps.setString(2,entity.getPrenume());
            ps.setInt(3,entity.getId());

            int randuri =ps.executeUpdate();
            if(randuri ==0)return entity;
            return null;
        }
        catch (SQLException e)
        {
            throw new RepositoryException("Eroare la actualizarea utilizatorului: "+e.getMessage(),e);
        }

    }
}